('de900000-0000-4000-8000-000000000001','f1eb0b1f-be17-4ade-b013-e706ea825d0e','cfo-dashboard','CFO · Trailing 12 months · A-','[]'::jsonb,'{"period_label": "Trailing 12 months", "focus_area": "all", "context_summary": "Evergreen Grounds landscaping, $2.8M, 16% net."}'::jsonb,'{"period_label": "Trailing 12 months", "summary": "A strong, improving year. Revenue up 22% and net margin up from 12 to 16 as the recurring maintenance book grew. Cash is healthy at about nine weeks of payroll and the line of credit is untouched. The watch item is not the money, it is whether a second crew can be staffed to the same standard without you on site.", "health_grade": "A-", "kpis": [{"label": "Revenue (TTM)", "value": "$2.8M", "period_over_period": {"direction": "up", "delta": "+22%", "note": "vs last year"}, "is_estimate": false, "note": "Driven by the commercial maintenance book"}, {"label": "Net margin", "value": "16%", "period_over_period": {"direction": "up", "delta": "+4 pts", "note": "from 12%"}, "is_estimate": false, "note": "Routed maintenance beats one-off installs per hour"}, {"label": "Recurring revenue", "value": "64%", "period_over_period": {"direction": "up", "delta": "+6 pts", "note": "as contracts renew"}, "is_estimate": false, "note": "The base the business runs on"}, {"label": "Cash on hand", "value": "$240k", "period_over_period": null, "is_estimate": false, "note": "About nine weeks of payroll"}, {"label": "Gross margin", "value": "45%", "period_over_period": null, "is_estimate": false, "note": ""}], "commentary": "The healthy pattern: margin rose while revenue grew, which means the extra work is being won at prices that carry it. Most owners your size see the opposite. Hold that discipline into the second-crew decision.", "green_flags": ["Margin improving alongside growth", "Nearly two thirds of revenue recurring", "No debt drawn on the line of credit"], "red_flags": ["Growth is outrunning one crew''s capacity", "The quality standard still depends on you on site"], "trends": [{"metric": "Revenue", "direction": "up", "note": "+22% year over year"}, {"metric": "Net margin", "direction": "up", "note": "12% to 16%"}, {"metric": "Recurring share", "direction": "up", "note": "growing as commercial contracts renew"}], "accountant_questions": ["Confirm the GST remittance is set aside from the quarter''s collections", "Check the receivables ageing on the two largest commercial accounts"], "next_actions": ["Promote and settle a crew lead before adding a second crew", "Model a second crew at 11% first-year margin, not 16%"], "books": ["Traction (Gino Wickman)", "The E-Myth Revisited (Michael Gerber)"]}'::jsonb),
('de900000-0000-4000-8000-000000000001','f1eb0b1f-be17-4ade-b013-e706ea825d0e','cash-flow','Cash Flow · October 2026','[]'::jsonb,'{"data_source": "manual", "starting_balance": 240000, "comfort_threshold": 80000, "concerns": "Whether a second crew fits the cash picture", "context_summary": "Evergreen Grounds, strong recurring base."}'::jsonb,'{"summary": "Cash-positive every week of the quarter. You never come close to the comfort line, even in the week the equipment service and insurance land together. A second crew''s ramp fits inside this without touching the line of credit.", "runway_weeks": null, "starting_balance": 240000, "comfort_threshold": 80000, "weeks": [{"week": 1, "week_ending": "Oct 13", "inflow": 68000, "outflow": 58000, "net": 10000, "ending_balance": 250000}, {"week": 2, "week_ending": "Oct 20", "inflow": 72000, "outflow": 60000, "net": 12000, "ending_balance": 262000}, {"week": 3, "week_ending": "Oct 27", "inflow": 66000, "outflow": 59000, "net": 7000, "ending_balance": 269000}, {"week": 4, "week_ending": "Nov 3", "inflow": 70000, "outflow": 61000, "net": 9000, "ending_balance": 278000}, {"week": 5, "week_ending": "Nov 10", "inflow": 108000, "outflow": 60000, "net": 48000, "ending_balance": 326000, "note": "Large strata invoice clears"}, {"week": 6, "week_ending": "Nov 17", "inflow": 69000, "outflow": 62000, "net": 7000, "ending_balance": 333000}, {"week": 7, "week_ending": "Nov 24", "inflow": 64000, "outflow": 60000, "net": 4000, "ending_balance": 337000}, {"week": 8, "week_ending": "Dec 1", "inflow": 67000, "outflow": 92000, "net": -25000, "ending_balance": 312000, "note": "Annual equipment service + insurance"}, {"week": 9, "week_ending": "Dec 8", "inflow": 71000, "outflow": 61000, "net": 10000, "ending_balance": 322000}, {"week": 10, "week_ending": "Dec 15", "inflow": 70000, "outflow": 60000, "net": 10000, "ending_balance": 332000}, {"week": 11, "week_ending": "Dec 22", "inflow": 66000, "outflow": 59000, "net": 7000, "ending_balance": 339000}, {"week": 12, "week_ending": "Dec 29", "inflow": 73000, "outflow": 62000, "net": 11000, "ending_balance": 350000}, {"week": 13, "week_ending": "Jan 5", "inflow": 69000, "outflow": 60000, "net": 9000, "ending_balance": 359000}], "lowest_point": {"week": 1, "balance": 250000, "note": "Lowest ending balance, still well above the comfort line"}, "key_events": [{"when": "Week 5", "event": "Large strata maintenance invoice clears", "amount": 40000, "direction": "inflow"}, {"when": "Week 8", "event": "Annual equipment service and insurance renewal", "amount": 30000, "direction": "outflow"}], "risks": ["A second-crew ramp would lower these net numbers until the new routes fill", "The week 5 inflow depends on the strata account paying on time"], "actions": ["Keep the comfort line at 80k through any second-crew ramp", "Confirm the strata account''s payment timing before committing the crew"]}'::jsonb),
('de900000-0000-4000-8000-000000000001','f1eb0b1f-be17-4ade-b013-e706ea825d0e','decision','Whether to add a second maintenance crew now, or wait until spring','[]'::jsonb,'{"decision": "Add a second maintenance crew now or wait until spring", "stakes": "$190k/yr; two March strata bids", "deadline": "Before the March bids", "context_summary": "Evergreen Grounds, 64% recurring, Marcus crew lead candidate."}'::jsonb,'{"decision": "Whether to add a second maintenance crew now, or wait until spring", "stakes": "The commercial maintenance book has grown faster than one crew can service, and two large strata contracts go to bid in March. A second crew is roughly $190k all in for the year. The question is not whether the work is there, it is whether the business can run a second crew to the same standard without the owner on it.", "angles": [{"name": "The cash case", "leaning": "for", "argument": "Recurring maintenance is 64% of revenue and renews, so a second crew is backed by predictable income. At 16% net and $240k in the bank you can carry the ramp without touching the line of credit.", "weakest_point": "It assumes the two strata bids land. If both go elsewhere, you have sized a crew for work that did not arrive."}, {"name": "The people case", "leaning": "mixed", "argument": "What gates a second crew is a lead who runs a site the way you would. Marcus is strong, but promoting him pulls your best hand off the crew already earning the renewals.", "weakest_point": "You have not asked Marcus whether he wants to lead. That conversation is free and it decides the plan."}, {"name": "The margin case", "leaning": "for", "argument": "Margin rose from 12% to 16% as the recurring book grew. A second crew weighted to maintenance compounds the thing already working.", "weakest_point": "A new crew runs below mature margin while routes fill. Model year one near 11%, not 16%."}], "conflict": "The cash and margin cases say go now. The people case says the real constraint is a single promotion, and rushing it could cost you the crew carrying the renewals. The money is ready before the organisation is.", "landing": {"recommendation": "Add the crew, but promote and settle Marcus first, and time the hire to the March bids rather than ahead of them.", "reasoning": "You can plainly afford it, so money is not the deciding factor, the crew lead is. Give Marcus six weeks running the current crew with you stepping back, and you will know before March whether the standard holds without you.", "my_weakest_point": "I am treating the March bids as the trigger. If a contract comes up sooner, the sequence compresses and you may have to promote and crew up at once."}, "cannot_see": [{"gap": "Whether Marcus actually wants to lead, or is happy on the tools", "who_would_know": "Marcus, in one conversation"}, {"gap": "How the two March strata bids are really trending", "who_would_know": "Your estimator"}, {"gap": "Whether the current crew keeps its renewal rate if its best hand moves up", "who_would_know": "The crew and the client feedback"}], "drawn_from": ["Your QuickBooks figures", "The maintenance contract renewals", "Roadmap milestones", "Two earlier talks about promoting from the crew"], "next_asks": [{"ask": "Ask Marcus this week whether he wants to run a crew", "why": "The whole plan rests on it and the conversation costs nothing"}, {"ask": "Put a realistic win probability on the two March bids", "why": "It decides whether you crew up ahead of them or after"}, {"ask": "Model the second crew at 11% first-year margin", "why": "A new route runs below mature margin until it fills"}]}'::jsonb),
('de900000-0000-4000-8000-000000000001','f1eb0b1f-be17-4ade-b013-e706ea825d0e','exit-readiness','Exit Readiness · C+ · October 2026','[]'::jsonb,'{"owner_dependence": "high", "recurring_pct": "64", "top_customer_pct": "18", "exit_timeline": "2-3 years", "context_summary": "Evergreen Grounds."}'::jsonb,'{"overall_score": 64, "grade": "C+", "summary": "A genuinely sellable foundation held back by one thing: the business still runs on you. The recurring base and clean books are what a buyer pays for; the owner dependence is what they discount. Close that gap and this moves from a job you own to an asset you can hand on.", "drivers": [{"name": "Financial Performance", "score": 78, "weight_pct": 16, "note": "16% net and growing, above the trade average"}, {"name": "Recurring Revenue", "score": 82, "weight_pct": 16, "note": "64% recurring, the strongest part of the story"}, {"name": "Owner Dependence", "score": 38, "weight_pct": 18, "note": "The quality standard still depends on you on site. The main drag."}, {"name": "Customer Concentration", "score": 66, "weight_pct": 12, "note": "Healthy spread, watch the two largest commercial accounts"}, {"name": "Growth Potential", "score": 72, "weight_pct": 10, "note": "Commercial book growing faster than capacity"}, {"name": "Differentiation", "score": 60, "weight_pct": 10, "note": "Reliability and standard, not yet documented as a system"}, {"name": "Systems & Documentation", "score": 48, "weight_pct": 12, "note": "Playbooks started, routes not yet fully written down"}, {"name": "Revenue Diversity", "score": 58, "weight_pct": 6, "note": "Residential plus commercial, seasonally weighted"}], "strengths": ["Two thirds of revenue recurring and renewing", "Margin improving as you grow", "No debt on the line of credit"], "risks": ["The business cannot yet run a day without you on site", "The quality standard lives in your head, not a system", "A second crew''s standard is unproven without you"], "quick_wins": ["Promote and settle a crew lead, then step back for six weeks", "Write the maintenance routes down as playbooks", "Document the two largest accounts'' service expectations"], "books": ["Built to Sell (John Warrillow)", "The E-Myth Revisited (Michael Gerber)"]}'::jsonb),
('de900000-0000-4000-8000-000000000001','f1eb0b1f-be17-4ade-b013-e706ea825d0e','hiring-scorecard','Crew lead · October 2026','[]'::jsonb,'{"role_title": "Crew lead", "why_now": "To run a second crew without the owner", "context_summary": "Evergreen Grounds."}'::jsonb,'{"mission": "Run a maintenance crew to the Evergreen standard without the owner on site, so the business can take on a second crew and grow the commercial book.", "outcomes": ["Every site on the route meets the agreed standard each visit, confirmed by photos and renewals", "The crew runs a full day without calling the owner for direction", "New crew members are trained to standard within 30 days"], "certifications_required": ["Valid driver''s licence", "First aid, or willing to certify within 30 days"], "competencies": [{"name": "Standard-holding", "definition": "Notices and fixes a site that is not to standard without being told"}, {"name": "Crew leadership", "definition": "Keeps a small crew moving and calm under a tight schedule"}, {"name": "Client-facing judgement", "definition": "Handles an on-site client question without escalating everything"}], "interview_questions": ["Tell me about a site you turned around that was being done badly", "How do you keep a crew on schedule when access is delayed?", "A client stops you on site unhappy about the edging. What do you do?"], "red_flags": ["Needs every decision confirmed", "Talks about speed before quality", "No examples of leading others"], "ramp_plan": {"day_30": "Running the existing crew with the owner checking in, not directing", "day_60": "Owner off site two days a week, standard holding", "day_90": "Owner off the crew entirely, ready to seed the second crew"}, "compensation_note": "Position above a senior crew wage to reflect the standard-holding responsibility. It is cheaper than the owner staying on the tools."}'::jsonb),
('de900000-0000-4000-8000-000000000001','f1eb0b1f-be17-4ade-b013-e706ea825d0e','org-chart','Org Chart · Next 12 months · October 2026','[]'::jsonb,'{"horizon": "12m", "current_team": "Owner + 5 crew", "goal": "Owner off the tools", "context_summary": "Evergreen Grounds."}'::jsonb,'{"summary": "The shape that lets you step off the tools: a crew lead under you now, a second crew lead as the commercial book grows, and an office seat so scheduling and client calls stop living on your phone.", "horizon_label": "Next 12 months", "roles": [{"title": "Owner / Operator", "reports_to": null, "type": "transition", "headcount": 1, "hire_by": null, "responsibilities": ["Sales and estimating", "Standard and hiring", "Stepping back from daily crew direction"], "key_kpis": ["Net margin", "Recurring book growth"], "note": "Moving from on-the-tools to running the business"}, {"title": "Crew Lead, Crew 1", "reports_to": "Owner / Operator", "type": "transition", "headcount": 1, "hire_by": null, "responsibilities": ["Runs the main maintenance route to standard", "Trains the crew", "On-site client contact"], "key_kpis": ["Renewal rate", "Sites to standard"], "note": "Promote Marcus"}, {"title": "Office / Scheduling", "reports_to": "Owner / Operator", "type": "new-hire", "headcount": 1, "hire_by": "January 2027", "responsibilities": ["Scheduling and routes", "Client calls and renewals", "Invoicing support"], "key_kpis": ["On-time scheduling", "Invoice turnaround"], "note": "Takes the phone off the owner"}, {"title": "Crew Lead, Crew 2", "reports_to": "Owner / Operator", "type": "new-hire", "headcount": 1, "hire_by": "March 2027", "responsibilities": ["Runs the second maintenance crew", "Covers the new strata contracts"], "key_kpis": ["New-route margin", "Sites to standard"], "note": "Timed to the March strata bids"}], "hiring_sequence": [{"order": 1, "role": "Office / Scheduling", "hire_by": "January 2027", "why_this_first": "Frees your time immediately and is lower risk than a crew lead", "unlocks": "You can focus on settling the crew lead and the March bids"}, {"order": 2, "role": "Crew Lead, Crew 2", "hire_by": "March 2027", "why_this_first": "Only once Crew 1''s standard holds without you", "unlocks": "A second crew for the commercial growth"}], "owner_transition": {"from": "On the tools, running every site", "to": "Running the business: sales, standard, numbers", "stop_doing": ["Directing the daily crew", "Fielding every scheduling call"], "start_doing": ["Settling the crew lead", "Working the March bids", "Reading the numbers weekly"]}, "risks": ["Promoting the crew lead too fast and slipping the standard on both crews", "Hiring the second crew ahead of the work landing"], "books": ["Traction (Gino Wickman)", "Rocket Fuel (Wickman & Winters)"]}'::jsonb);
